import re,os
root='/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild'
def path(mod):
    return os.path.join(root, mod.replace('.','/')+'.lean')
seen=set(); stack=['AlgebraicJacobian.Picard.Pic0SigmaSheaf']
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    p=path(m)
    if not os.path.exists(p): continue
    for line in open(p):
        mm=re.match(r'import\s+(AlgebraicJacobian[\w.]*)',line)
        if mm: stack.append(mm.group(1))
print("closure size:",len(seen))
bad=[]
for m in sorted(seen):
    p=path(m)
    if not os.path.exists(p): continue
    for i,line in enumerate(open(p),1):
        if re.search(r'(^|[^\w])sorry([^\w]|$)',line):
            bad.append(f"{p}:{i}: {line.strip()[:120]}")
print("sorry occurrences in closure:",len(bad))
for b in bad: print(b)
EOF
